import{_ as t,C as n,o as i,c as o,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const l="/joinwell52/assets/covers/daily-2026-08-19-mobile-decision-boundary-en.png",f=JSON.parse('{"title":"How Do You Stay in Control of an AI Team After Leaving Your Computer? A Two-Plane Design for Local Execution and Mobile Control","description":"","frontmatter":{"title":"How Do You Stay in Control of an AI Team After Leaving Your Computer? A Two-Plane Design for Local Execution and Mobile Control","date":"2026-08-19","column":"digital-employee","category":"daily","article_type":"project-research","edition":"research-center","research_question":"How can a local agent team separate authoritative PC execution from constrained mobile control while handling weak networks, revision changes, device revocation, and approval boundaries?","summary":"The computer keeps execution and authoritative facts while the phone provides a revision-bound view and decision surface; uncertain requests return to local authority instead of creating a second truth.","item_id":"MANUAL-20260819-MOBILE-CONTROL","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-19-local-runtime-mobile-control-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-fact-claim-matrices.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-experiment-run-log.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/03-independent-final-package-review-round2.md"]},"headers":[],"relativePath":"en/digital-employee/2026-08-19-local-runtime-mobile-control.md","filePath":"en/digital-employee/2026-08-19-local-runtime-mobile-control.md","lastUpdated":1787125010000}'),c={name:"en/digital-employee/2026-08-19-local-runtime-mobile-control.md"};function d(p,e,h,u,m,b){const a=n("ArticleCover");return i(),o("div",null,[r(a,{image:"/assets/covers/daily-2026-08-19-local-runtime-mobile-control-cover.png",kicker:"Digital Employee · Project Research",title:"How Do You Stay in Control of an AI Team After Leaving Your Computer? A Two-Plane Design for Local Execution and Mobile Control",summary:"The computer keeps execution and authoritative facts while the phone provides a revision-bound view and decision surface; uncertain requests return to local authority instead of creating a second truth.",version:"MANUAL-20260819-MOBILE-CONTROL",status:"Independent Editorial PASS · 2026-08-19",languageHref:"/zh/digital-employee/2026-08-19-local-runtime-mobile-control",languageLabel:"中文"}),e[0]||(e[0]=s(`<h1 id="how-do-you-stay-in-control-of-an-ai-team-after-leaving-your-computer-a-two-plane-design-for-local-execution-and-mobile-control" tabindex="-1">How Do You Stay in Control of an AI Team After Leaving Your Computer? A Two-Plane Design for Local Execution and Mobile Control <a class="header-anchor" href="#how-do-you-stay-in-control-of-an-ai-team-after-leaving-your-computer-a-two-plane-design-for-local-execution-and-mobile-control" aria-label="Permalink to &quot;How Do You Stay in Control of an AI Team After Leaving Your Computer? A Two-Plane Design for Local Execution and Mobile Control&quot;">​</a></h1><p><strong>Series map:</strong> start with <a href="/joinwell52/en/engineering/2026-08-19-taskbook-to-task-graph">the long-requirement work graph</a>, then use <a href="/joinwell52/en/engineering/2026-08-19-agent-dispatch-fault-injection">fault injection</a> to test the runtime. This article covers remote observation and bounded human decisions after leaving the computer.</p><h2 id="in-ten-seconds" tabindex="-1">In ten seconds <a class="header-anchor" href="#in-ten-seconds" aria-label="Permalink to &quot;In ten seconds&quot;">​</a></h2><p>The computer keeps execution and authoritative facts. The phone provides a constrained view and a small decision surface. Every mobile action returns to the latest server-side version for authority, version, and duplicate-request checks.</p><p>At 7 p.m., a refactor is still running on a computer at home. DEV has submitted changes, OPS is running integration tests, and QA has just found a failure. The human is on a train. What the phone needs is not a miniature IDE. It needs three answers: what happened, which decision requires me, and whether a weak connection can execute my action twice.</p><p>The most dangerous design is a second task database inside the phone app. PC and PWA quickly acquire separate truths: the local task is in review while the cached phone still says active; an offline approval targets an old revision and is later replayed against new work.</p><p>A cleaner boundary separates an execution plane from a control plane.</p><blockquote><p><strong>The PC Runtime owns execution and durable facts. The PWA observes those same facts and sends a small set of human decisions back with version, reason, and an idempotency key—a unique request number that prevents repeated taps from creating repeated decisions.</strong></p></blockquote><h2 id="a-pwa-is-not-a-second-runtime" tabindex="-1">A PWA is not a second Runtime <a class="header-anchor" href="#a-pwa-is-not-a-second-runtime" aria-label="Permalink to &quot;A PWA is not a second Runtime&quot;">​</a></h2><p>The <a href="https://www.w3.org/TR/appmanifest/" target="_blank" rel="noreferrer">W3C Web App Manifest</a> provides installation metadata, start URLs, and application scope. <a href="https://www.w3.org/TR/service-workers/" target="_blank" rel="noreferrer">Service Workers</a> provide event-driven network mediation and caching. Browsers may terminate a service worker and restart it when an event arrives. That is useful for an offline shell, caching, and notifications; it is not a reliable process for a model session that runs for hours.</p><p>The first system boundary should therefore be explicit:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PC / Execution &amp; Fact Plane              Mobile / Bound Control Plane</span></span>
<span class="line"><span>┌───────────────────────────┐            ┌──────────────────────────┐</span></span>
<span class="line"><span>│ CodeFlowMu Runtime        │            │ PWA                      │</span></span>
<span class="line"><span>│ - Watch / dispatch        │            │ - Team status            │</span></span>
<span class="line"><span>│ - Model sessions          │&lt;--API/SSE--│ - Task / report detail    │</span></span>
<span class="line"><span>│ - Tests / evidence        │            │ - Approval with reason    │</span></span>
<span class="line"><span>│ - FCoP work artifacts     │            │ - Device / link status    │</span></span>
<span class="line"><span>└─────────────┬─────────────┘            └────────────┬─────────────┘</span></span>
<span class="line"><span>              │ authoritative files                   │ no second task DB</span></span>
<span class="line"><span>              v                                       │</span></span>
<span class="line"><span>      TASK / REPORT / REVIEW / events &lt;───────────────┘</span></span></code></pre></div><p>FCoP remains a protocol in this design: it defines work artifacts, path-based state, and event history. CodeFlowMu is the engineering rail that runs agents, observes files, starts sessions, and exposes PC/PWA services. PWA behavior must not be advertised as a capability of the protocol.</p><h2 id="what-the-phone-minimally-needs-to-show" tabindex="-1">What the phone minimally needs to show <a class="header-anchor" href="#what-the-phone-minimally-needs-to-show" aria-label="Permalink to &quot;What the phone minimally needs to show&quot;">​</a></h2><p>A useful control plane is not measured by page count. A minimum product can have six surfaces:</p><ol><li><strong>Team status:</strong> which roles are idle, busy, blocked, or offline, with an observation time.</li><li><strong>Task state and hierarchy:</strong> current task, parent/child relations, revision, location, and blocking reason.</li><li><strong>Reports and evidence:</strong> who asserted what, whether tests are PASS/FAIL/NOT RUN, and where evidence lives.</li><li><strong>Pending decisions:</strong> objects awaiting approve, reject, pause, or rework authority.</li><li><strong>Activity:</strong> append-only meaningful events, rather than treating chat bubbles as a state machine.</li><li><strong>Device status:</strong> bound devices, last seen, session expiry, and LAN/Gateway reachability.</li></ol><p>Every surface must answer, “Which authoritative record produced this value?” If the list comes from a file reader, details from a separate database replica, and notifications from in-memory events, the three will eventually disagree about one task.</p><p><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-architecture-paper-a1.0" target="_blank" rel="noreferrer">TMPA Architecture Paper A1.0</a> calls for a stable primary carrier for governed work. Multiple writers use separate asynchronous streams that a deterministic Reader aggregates. Applied to mobile control, this does not require “files as the only database.” It requires every cache and index to remain an explicitly derived view rather than quietly acquiring primary authority.</p><h2 id="binding-is-a-device-lifecycle-not-a-permanent-qr-code" tabindex="-1">Binding is a device lifecycle, not a permanent QR code <a class="header-anchor" href="#binding-is-a-device-lifecycle-not-a-permanent-qr-code" aria-label="Permalink to &quot;Binding is a device lifecycle, not a permanent QR code&quot;">​</a></h2><p>The current CodeFlowMu <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/codeflowmu-shell/src/mobile/mobileBindStore.ts" target="_blank" rel="noreferrer">binding store</a> separates a short-lived pending binding from durable device identity. The durable device record stores a session-token hash. To return the same result for a repeated browser request, an in-process completion record retains the original session token while that record remains in memory. Eligibility to replay the first result ends after ten minutes; the expired record is removed lazily when that binding ID is accessed again, not by a timer at the ten-minute mark. That tradeoff belongs in the threat model; it must not be simplified to “the system only stores hashes.” The presence of code is not a security certification.</p><p>A stricter target binding contract should include the following. The current ten-minute idempotent replay window is an intentional compatibility policy, not strict single use:</p><ol><li>The PC generates a short-lived, single-use entry.</li><li>Confirmation atomically consumes the pending token; a same-token network retry returns the same result only within a bounded window, while wrong, conflicting, or expired tokens are rejected.</li><li>The server issues an expiring, revocable device session.</li><li>The client stores only required credentials; logs, screenshots, and URLs do not echo them.</li><li>The PC can list, disable, and rotate devices.</li><li>High-risk actions may require fresh authentication rather than a browsing session.</li></ol><p>Binding links, QR codes, session tokens, real task bodies, and chat messages do not belong in public screenshots, Git, or ordinary debug logs. “Do not leak this” in a prompt is not a security boundary; Core S1.0&#39;s separation of role authority applies to UI actions too.</p><h2 id="a-mobile-approval-is-not-a-status-edit" tabindex="-1">A mobile approval is not a <code>status</code> edit <a class="header-anchor" href="#a-mobile-approval-is-not-a-status-edit" aria-label="Permalink to &quot;A mobile approval is not a \`status\` edit&quot;">​</a></h2><p>The dangerous request is simply “task 1 is approved.” A tunnel drops the connection, the phone retries three times, and meanwhile the task changes. The server now has repeated approval writes with no proof of which version the user saw.</p><p>A safer target protocol sends an object ID, observed version fingerprint, decision, non-empty reason, and unique request number. This is an architectural example, not a claim about a published CodeFlowMu API or an already connected mobile Planning Gate.</p><p>Suppose QA writes a failed report on the PC and the phone displays “rework decision required.” When an administrator taps approve-rework, the client should submit the object ID, observed revision, decision enum, non-empty reason, idempotency key, and client time. The server re-reads canonical state, validates authority and revision, appends the decision, and returns a new server version.</p><p>Weak networks require fail-closed behavior: when version, authority, or outcome is uncertain, the system does not proceed.</p><ul><li>If the revision changed, reject the old decision and require a reread.</li><li>If an idempotency key is replayed, return the first result without appending another decision.</li><li>If the request times out, display “outcome unknown,” not success.</li><li>Approval means the Runtime may attempt work; it does not mean execution completed.</li><li>Execution still returns through REPORT, tests, and independent review evidence.</li></ul><p><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-core-specification-s1.0" target="_blank" rel="noreferrer">TMPA Core S1.0</a> separates execution claims, validation results, and acceptance decisions. Mobile UI transports human authority into the same governance chain; convenience does not permit those roles to collapse.</p><p><img src="`+l+'" alt="Target decision contract in which a phone sends a revision-bound, idempotent request to local authority for device, permission, revision, and replay checks"></p><p><em>Figure 1. This is the target decision boundary, not a claim about the current mobile API. The phone remains an entry point; the authoritative service should recheck device session, role capability, target revision, and idempotency. FCoP REVIEW and Operation Approval remain separate planes. Source: TMPA Core S1.0, FCoP v3, and the verified boundaries of current CodeFlowMu device and operation-approval implementations.</em></p><h2 id="lan-and-gateway-are-reachability-paths-not-fact-sources" tabindex="-1">LAN and Gateway are reachability paths, not fact sources <a class="header-anchor" href="#lan-and-gateway-are-reachability-paths-not-fact-sources" aria-label="Permalink to &quot;LAN and Gateway are reachability paths, not fact sources&quot;">​</a></h2><p>On the same network, a phone may connect directly to the PC service. Away from home, a constrained Gateway may relay requests and events. The paths change reachability. They must not change the authoritative source of TASK, REPORT, approval, and device state.</p><p>On 2026-08-19, we reran the current CodeFlowMu <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/codeflowmu-shell/src/__tests__/lanNetwork.test.ts" target="_blank" rel="noreferrer">LAN-address test file</a>: <strong>5 tests passed</strong>. Exact commands, environment, exit codes, and raw output are preserved in the <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-experiment-run-log.md" target="_blank" rel="noreferrer">experiment run log</a>. That supports a limited address-selection implementation claim. It does not establish public reachability, NAT behavior, TLS, Gateway longevity, or end-to-end mobile security.</p><p>The current open-edition implementation still keeps remote mobile publication read-only/external, but this run found that current permission semantics and an older regression test no longer agree. Exact error identifiers belong in the experiment record, not the article&#39;s main narrative. The general lesson is stronger: <strong>authority must align across backend enforcement, user-facing permission language, and regression tests</strong>, or the phone may display a capability that does not exist. A test detects drift; product authority must decide the contract and synchronize all three surfaces.</p><h2 id="weak-networks-and-caches-stale-views-may-be-readable-stale-decisions-must-not-execute" tabindex="-1">Weak networks and caches: stale views may be readable; stale decisions must not execute <a class="header-anchor" href="#weak-networks-and-caches-stale-views-may-be-readable-stale-decisions-must-not-execute" aria-label="Permalink to &quot;Weak networks and caches: stale views may be readable; stale decisions must not execute&quot;">​</a></h2><p>A PWA may cache its shell and the most recent read-only snapshot, but the page must display data version, server time, and connection state. A practical policy is:</p><ul><li>Offline users may read a task explicitly labeled “as of 19:02.”</li><li>The client does not cache an approval token that can be replayed unconditionally.</li><li>Reconnection performs version reconciliation before enabling write buttons.</li><li>Server events trigger incremental refresh, while full reconciliation repairs missed events.</li><li>An old client, incompatible schema, or uncertain authority forces read-only mode.</li></ul><p>This direction is consistent with local-first research on local ownership, offline availability, and cross-device coordination. That paper does not validate our implementation. CodeFlowMu still needs end-to-end experiments for real weak networks, clock skew, cache corruption, device revocation, and Gateway failures.</p><h2 id="a-15-point-acceptance-checklist" tabindex="-1">A 15-point acceptance checklist <a class="header-anchor" href="#a-15-point-acceptance-checklist" aria-label="Permalink to &quot;A 15-point acceptance checklist&quot;">​</a></h2><p><strong>Facts and display</strong></p><ul><li>List and detail views resolve to the same canonical artifact and revision.</li><li>Cached views show observation time instead of impersonating real-time state.</li><li>REPORT, REVIEW, decision, and execution state are not compressed into one <code>done</code> value.</li><li>Full reconciliation repairs missed real-time events.</li></ul><p><strong>Binding and authority</strong></p><ul><li>The pending binding token expires and is consumed once; bounded idempotent replay returns only the same result, and the token cannot be recovered from logs.</li><li>Device sessions can expire, rotate, and be revoked.</li><li>The server rechecks roles for high-risk actions instead of trusting visible buttons.</li><li>A PWA screen does not confer external publication authority on the open edition.</li></ul><p><strong>Mobile writes</strong></p><ul><li>Every decision carries object ID, current revision, decision, reason, and idempotency key.</li><li>A changed revision makes the stale decision fail closed.</li><li>Timeout produces “unknown,” never client-declared success.</li><li>Approval and execution success are displayed separately.</li></ul><p><strong>Network and privacy</strong></p><ul><li>LAN and Gateway use the same fact and authority services.</li><li>Weak network, disconnect, repeated request, server restart, and device revocation have regression coverage.</li><li>Public screenshots, repositories, telemetry, and ordinary logs exclude QR codes, binding URLs, tokens, and real task text.</li></ul><p>A cloud Runtime is another valid architecture. If tasks execute in a remote sandbox, the phone may directly control that cloud authority. This article addresses the failure and trust model of a local agent team; it does not argue that all agents must run on a PC.</p><p>For a local system, the best mobile client is not the one with the most features. It is the one that lets a human leave the desk, see the same facts, make a small number of authorized decisions, and refuse to manufacture a second truth when network and version are uncertain.</p><h2 id="how-tmpa-fcop-codeflowmu-and-mobile-divide-responsibility" tabindex="-1">How TMPA, FCoP, CodeFlowMu, and Mobile divide responsibility <a class="header-anchor" href="#how-tmpa-fcop-codeflowmu-and-mobile-divide-responsibility" aria-label="Permalink to &quot;How TMPA, FCoP, CodeFlowMu, and Mobile divide responsibility&quot;">​</a></h2><p>These names describe four layers, not four competing products.</p><ol><li><strong>TMPA Core defines governance semantics.</strong> It specifies stable work carriers, role responsibility, lifecycle state, independent acceptance, conflict preservation, and deterministic reconstruction. A stable primary carrier is the stable reference point for governed work; TMPA does not declare that every system must use a PC or local disk. Its crucial boundary here is that an execution report is a fact claim, while acceptance is a decision made by an authorized role.</li><li><strong>FCoP projects collaboration into files.</strong> It defines TASK, REPORT, ISSUE, REVIEW, lifecycle locations, and transition events that people and tools can inspect. It does not choose a LAN address, issue device credentials, draw the mobile UI, or own an agent session.</li><li><strong>CodeFlowMu is the running engineering system.</strong> In the local deployment discussed here, the project root, Runtime, and server-side readers form the authoritative execution plane. CodeFlowMu runs agents and tests, checks dependencies and permissions, manages devices, and distinguishes task review from operation approval. That local authority is a CodeFlowMu deployment choice, not a universal TMPA requirement.</li><li><strong>CodeFlowMu Mobile PWA is a constrained remote surface.</strong> It displays server-derived facts and returns a small set of human requests to the same authority. It may cache a stale view, but it does not become a second Runtime or bypass server-side checks.</li></ol><p>Under the target decision contract described in this article, tapping Approve would send the target, observed revision, reason, and idempotency key. The authoritative service would then recheck the device session, role capability, current revision, and prior use of the request key. Current public CodeFlowMu code proves narrower pieces: device-session checks and a separate Operation Approval service whose server creates an action ID for a digest-bound attempt. It does not prove that the existing mobile route already accepts and enforces this client-supplied revision/idempotency contract. A future task-review path may record a decision in the applicable REVIEW chain; a high-risk Git or external-write action remains a separate operation approval. Later REPORT and verification evidence still determine what actually happened.</p><p>In one line: <strong>TMPA defines the governance semantics, FCoP defines the collaboration artifacts, CodeFlowMu owns local execution and authority checks, and the phone remains a bounded remote entry point.</strong></p><h2 id="primary-sources" tabindex="-1">Primary sources <a class="header-anchor" href="#primary-sources" aria-label="Permalink to &quot;Primary sources&quot;">​</a></h2><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-architecture-paper-a1.0" target="_blank" rel="noreferrer">TMPA Architecture Paper A1.0</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/tmpa-core-specification-s1.0" target="_blank" rel="noreferrer">TMPA Core Specification S1.0</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/en/publications/implementation-case-i1.0" target="_blank" rel="noreferrer">Implementation Case I1.0</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open" target="_blank" rel="noreferrer">CodeFlowMu Open</a></li><li><a href="https://www.w3.org/TR/appmanifest/" target="_blank" rel="noreferrer">W3C Web App Manifest</a></li><li><a href="https://www.w3.org/TR/service-workers/" target="_blank" rel="noreferrer">W3C Service Workers</a></li><li><a href="https://martin.kleppmann.com/2019/10/23/local-first-at-onward.html" target="_blank" rel="noreferrer">Local-first software paper</a></li></ul>',58))])}const v=t(c,[["render",d]]);export{f as __pageData,v as default};
